package project.init.account.domain.entity;import jakarta.persistence.CascadeType;import jakarta.persistence.Column;import jakarta.persistence.Entity;import jakarta.persistence.FetchType;import jakarta.persistence.Id;import jakarta.persistence.ManyToMany;import jakarta.persistence.PrePersist;import jakarta.persistence.PreUpdate;import jakarta.persistence.Table;import lombok.Getter;import lombok.Setter;import org.hibernate.annotations.Fetch;import org.hibernate.annotations.FetchMode;import java.time.Instant;import java.util.List;@Getter@Setter@Entity@Table(name = "account")public class Account {    @Id    @Column(name = "account_code", length = 50, nullable = false)    private String accountCode;    @Column(name = "password_hash", nullable = false, columnDefinition = "TEXT")    private String passwordHash;    @Column(name = "account_status", length = 10, nullable = false)    private String accountStatus = "ACTIVE";    @Column(name = "created_at", updatable = false)    private Instant createdAt;    @Column(name = "updated_at")    private Instant updatedAt;    @ManyToMany(fetch = FetchType.EAGER, cascade = CascadeType.MERGE)    @Fetch(value = FetchMode.SUBSELECT)    private List<Role> roles;    @PrePersist    protected void onCreate() {        createdAt = Instant.now();        updatedAt = Instant.now();    }    @PreUpdate    protected void onUpdate() {        updatedAt = Instant.now();    }}